from rest_framework.generics import RetrieveAPIView
from rest_framework.permissions import IsAuthenticated
from rest_framework.exceptions import PermissionDenied
from post_office.models import Email
from .serializers import OutboundEmailDetailSerializer

class QueuedEmailDetailView(RetrieveAPIView):
    permission_classes = [IsAuthenticated]
    serializer_class = OutboundEmailDetailSerializer

    def get_queryset(self):
        user = self.request.user
        if user.is_staff:
            return Email.objects.all()
        # Restrict email inspection to messages sent to or triggered by the authenticated user
        return Email.objects.filter(to__contains=user.email)
